__mods["config"] = function ()
-- =====================================================================
--  config — schema, validation and merging of engine configuration.
--
--  config.load(overrides) -> cfg, errors
--      Deep-merges `overrides` onto the defaults and validates the result.
--      `cfg` is nil when any error is found (never a partially valid cfg).
--  config.validate(cfg) -> ok, errors      (errors = sorted list of strings)
-- =====================================================================
local util = require ("util")
local defaults = require ("default_config")

local M = {}

M.SETUPS = { "PULLBACK_CONTINUATION", "TREND_CONTINUATION", "BREAKOUT_CONFIRMATION", "RANGE_REJECTION" }

-- In the QCS bundle only data.m1_window and runner.cooldown_bars can differ from
-- the fully validated defaults (they come from bounded QCS inputs); they are
-- re-checked here. test_qcs_bundle.lua proves agreement with the full validator.
function M.validate (cfg)
    local d = type (cfg) == "table" and cfg.data
    local r = type (cfg) == "table" and cfg.runner
    local ok = type (d) == "table" and type (r) == "table" and util.finite (d.m1_window)
        and d.m1_window % 1 == 0 and d.m1_window >= d.min_m1_bars and d.m1_window <= 2000
        and util.finite (r.cooldown_bars) and r.cooldown_bars % 1 == 0 and r.cooldown_bars >= 0 and r.cooldown_bars <= 100
    return ok, ok and {} or { "CONFIG_INVALID" }
end

local function merge (base, over, path, errs)
    for _, k in ipairs (util.sorted_keys (over)) do
        local v = over[k]
        if type (v) == "table" and type (base[k]) == "table" and k ~= "setups" then merge (base[k], v, path .. k .. ".", errs)
        else base[k] = util.deepcopy (v) end
    end
end

function M.defaults () return util.deepcopy (defaults) end

function M.load (overrides)
    local cfg = M.defaults ()
    local errs = {}
    if overrides ~= nil then
        if type (overrides) ~= "table" then return nil, { "overrides: must be a table" } end
        merge (cfg, overrides, "", errs)
    end
    local ok, verrs = M.validate (cfg)
    if not ok then return nil, verrs end
    return cfg, {}
end

return M
end
__mods["indicators"] = function ()
-- =====================================================================
--  indicators — array indicators over a window of CLOSED candles.
--
--  Every function takes plain arrays (index 1 = oldest) and returns an
--  array of the same length; positions without enough history are nil.
--  Value at index i only uses inputs at indices <= i (causal), so the
--  value of a closed candle never changes when later candles arrive
--  within the same window start.
--
--  Seeding: EMA/RMA start from the SMA of their first n inputs, ATR/RSI
--  use Wilder smoothing (official QCS library formulas: rma = 1/n).
--
--  indicators.compute(m1, cfg) computes all features ONCE per evaluation;
--  every analysis module reads this shared table (no recomputation).
-- =====================================================================
local M = {}

--- exponential (alpha = 2/(n+1)) or Wilder (alpha = 1/n) smoothing, SMA seeded
local function smooth (src, n, alpha, first)
    local out, sum, cnt, prev = {}, 0, 0, nil
    for i = 1, #src do
        local x = src[i]
        if x ~= nil and i >= (first or 1) then
            if prev == nil then
                sum, cnt = sum + x, cnt + 1
                if cnt == n then prev = sum / n; out[i] = prev end
            else
                prev = prev + alpha * (x - prev); out[i] = prev
            end
        end
    end
    return out
end
function M.ema (src, n) return smooth (src, n, 2 / (n + 1)) end
function M.rma (src, n) return smooth (src, n, 1 / n) end

--- simple moving average of src over [i-n+1-lag, i-lag] (rolling sum, O(len));
--- a nil input restarts the window
function M.sma (src, n, lag)
    lag = lag or 0
    local out, sum, cnt = {}, 0, 0
    for j = 1, #src do
        local x = src[j]
        if x == nil then sum, cnt = 0, 0
        else
            sum, cnt = sum + x, cnt + 1
            if cnt > n then sum, cnt = sum - src[j - n], n end
            if cnt == n and j + lag <= #src then out[j + lag] = sum / n end
        end
    end
    return out
end

function M.true_range (H, L, C)
    local out = {}
    for i = 1, #H do
        if i == 1 then out[i] = H[i] - L[i]
        else out[i] = math.max (H[i] - L[i], math.abs (H[i] - C[i - 1]), math.abs (L[i] - C[i - 1])) end
    end
    return out
end

function M.atr (H, L, C, n) return M.rma (M.true_range (H, L, C), n) end

--- Wilder RSI; flat input (no gains and no losses) gives 50
function M.rsi (C, n)
    local up, dn = {}, {}
    for i = 2, #C do
        local d = C[i] - C[i - 1]
        up[i], dn[i] = math.max (d, 0), math.max (-d, 0)
    end
    local au, ad = smooth (up, n, 1 / n, 2), smooth (dn, n, 1 / n, 2)
    local out = {}
    for i = 1, #C do
        local u, w = au[i], ad[i]
        if u ~= nil and w ~= nil then
            if w == 0 then out[i] = (u == 0) and 50 or 100 else out[i] = 100 - 100 / (1 + u / w) end
        end
    end
    return out
end

--- Kaufman efficiency ratio: |C[i]-C[i-n]| / sum |C[j]-C[j-1]| (0 noise .. 1 straight)
function M.efficiency (C, n)
    local out, d, path = {}, {}, 0
    for i = 2, #C do
        d[i] = math.abs (C[i] - C[i - 1])
        path = path + d[i]
        if i - n >= 2 then path = path - d[i - n] end
        if i > n then out[i] = path > 1e-12 and math.abs (C[i] - C[i - n]) / path or 0 end
    end
    return out
end

--- MACD histogram (line - signal)
function M.macd_hist (C, fast, slow, sig)
    local f, s = M.ema (C, fast), M.ema (C, slow)
    local line = {}
    for i = 1, #C do if f[i] ~= nil and s[i] ~= nil then line[i] = f[i] - s[i] end end
    local sg = smooth (line, sig, 2 / (sig + 1), slow)
    local out = {}
    for i = 1, #C do if line[i] ~= nil and sg[i] ~= nil then out[i] = line[i] - sg[i] end end
    return out
end

--- confirmed swing pivots. sgn = 1 highs, -1 lows. Pivot at j needs
--- strictly beyond the p bars on the left and >= the p bars on the right,
--- all of which must exist (closed) -> confirmed p bars after it happened.
function M.pivots (X, p, sgn)
    local out = {}
    for j = p + 1, #X - p do
        local v, ok = sgn * X[j], true
        for k = j - p, j - 1 do if not (v > sgn * X[k]) then ok = false; break end end
        if ok then for k = j + 1, j + p do if not (v >= sgn * X[k]) then ok = false; break end end end
        if ok then out[#out + 1] = { i = j, price = X[j] } end
    end
    return out
end

--- full feature set for a validated, chronological window of closed M1 candles
function M.compute (m1, cfg)
    local ind = cfg.indicators
    local O, H, L, C, T = {}, {}, {}, {}, {}
    for i, b in ipairs (m1) do O[i], H[i], L[i], C[i], T[i] = b.o, b.h, b.l, b.c, b.t end
    local atr = M.atr (H, L, C, ind.atr_len)
    local f = {
        n = #m1, O = O, H = H, L = L, C = C, T = T,
        ema_f = M.ema (C, ind.ema_fast), ema_m = M.ema (C, ind.ema_mid), ema_s = M.ema (C, ind.ema_slow),
        atr = atr,
        atr_base = M.sma (atr, ind.atr_base_len, 1),     -- baseline excludes the candle itself
        rsi = M.rsi (C, ind.rsi_len),
        er = M.efficiency (C, ind.er_len),
        hist = M.macd_hist (C, ind.macd_fast, ind.macd_slow, ind.macd_signal),
    }
    local p = ind.pivot_len
    local ph, pl = M.pivots (H, p, 1), M.pivots (L, p, -1)
    local function last (list, k)
        local o = {}
        for i = math.max (1, #list - k + 1), #list do o[#o + 1] = list[i] end
        return o
    end
    f.swing_highs, f.swing_lows = last (ph, ind.max_levels), last (pl, ind.max_levels)
    return f
end

--- M5 context features (from closed M5 candles)
function M.compute_m5 (m5, cfg)
    local ind = cfg.indicators
    local H, L, C = {}, {}, {}
    for i, b in ipairs (m5) do H[i], L[i], C[i] = b.h, b.l, b.c end
    return { n = #m5, C = C, ema_f = M.ema (C, ind.m5_ema_fast), ema_s = M.ema (C, ind.m5_ema_slow),
             atr = M.atr (H, L, C, math.min (ind.atr_len, math.max (2, #m5 - 1))) }
end

return M
end
__mods["data_validation"] = function ()
-- =====================================================================
--  MODULE 1 — data_validation
--
--  prepare(input, cfg) -> result
--    input = { now = <unix seconds of the evaluation instant>,
--              m1  = { {t=, o=, h=, l=, c=, closed=?}, ... }  chronological,
--              m5  = optional, same shape with 300 s candles }
--    t = candle OPEN time (unix seconds, multiple of the period).
--    A candle is COMPLETE when closed == true, or closed == nil and
--    t + period <= now. closed == false or t + period > now -> incomplete.
--
--    result = { ok, errors = {codes}, warnings = {codes},
--               m1 = closed contiguous window (bounded by data.m1_window),
--               m5 = closed M5 candles, m5_source, stats = {...} }
--
--  Policy: any error -> ok = false and the engine returns WAIT. Nothing
--  is interpolated, sorted or repaired silently; only identical duplicate
--  candles may be dropped (configurable) and that is reported.
-- =====================================================================
local util = require ("util")

local M = {}

local function add (list, code) if not util.contains (list, code) then list[#list + 1] = code end end

--- structural check of one candle -> nil or an error code
function M.check_candle (b, period)
    if type (b) ~= "table" then return "CANDLE_NOT_TABLE" end
    local fin = util.finite
    if not (fin (b.t) and fin (b.o) and fin (b.h) and fin (b.l) and fin (b.c)) then return "CANDLE_FIELD_INVALID" end
    if math.floor (b.t) ~= b.t or b.t % period ~= 0 then return "TIMESTAMP_MISALIGNED" end
    if b.o <= 0 or b.h <= 0 or b.l <= 0 or b.c <= 0 then return "OHLC_NON_POSITIVE" end
    if b.h < b.l or b.h < math.max (b.o, b.c) or b.l > math.min (b.o, b.c) then return "OHLC_INCONSISTENT" end
    if b.closed ~= nil and type (b.closed) ~= "boolean" then return "CLOSED_FLAG_INVALID" end
    return nil
end

local function same (a, b) return a.o == b.o and a.h == b.h and a.l == b.l and a.c == b.c end

--- validates a candle list -> closed candles (chronological) + counters.
--- prefix distinguishes M1_/M5_ codes.
function M.closed_candles (list, period, now, cfg, prefix, errs, warns)
    local out, stats = {}, { input = 0, incomplete = 0, duplicates = 0 }
    if type (list) ~= "table" then add (errs, prefix .. "DATA_MISSING"); return out, stats end
    stats.input = #list
    local prev, seen_incomplete = nil, false
    for i = 1, #list do
        local b = list[i]
        local e = M.check_candle (b, period)
        if e then add (errs, prefix .. e)
        else
            local complete = (b.closed == true) or (b.closed == nil and b.t + period <= now)
            if b.t > now then add (errs, prefix .. "FUTURE_CANDLE")            -- look-ahead guard
            elseif b.closed == true and b.t + period > now then add (errs, prefix .. "CLOSED_FLAG_BEFORE_CLOSE")
            elseif prev and b.t < prev.t then add (errs, prefix .. "OUT_OF_ORDER")
            elseif prev and b.t == prev.t then
                stats.duplicates = stats.duplicates + 1
                if not same (b, prev) or (b.closed ~= prev.closed) then add (errs, prefix .. "DUPLICATE_CONFLICT")
                elseif not cfg.data.dedupe_identical then add (errs, prefix .. "DUPLICATE_CANDLE")
                else add (warns, prefix .. "DUPLICATE_DROPPED") end
            elseif not complete then
                stats.incomplete = stats.incomplete + 1
                add (warns, prefix .. "INCOMPLETE_DROPPED")
                prev, seen_incomplete = b, true
            else
                if seen_incomplete then add (errs, prefix .. "INCOMPLETE_BEFORE_CLOSED") end
                out[#out + 1] = { t = b.t, o = b.o, h = b.h, l = b.l, c = b.c }
                prev = b
            end
        end
    end
    return out, stats
end

--- aggregate closed M1 candles into clock-aligned M5 buckets
function M.aggregate_m5 (m1, now, cfg)
    local P, need = cfg.data.m5_period, cfg.data.m5_min_minutes
    local out, cur = {}, nil
    local function flush ()
        if cur and cur.n >= need and cur.t + P <= now then
            out[#out + 1] = { t = cur.t, o = cur.o, h = cur.h, l = cur.l, c = cur.c, minutes = cur.n }
        end
    end
    for _, b in ipairs (m1) do
        local k = b.t - b.t % P
        if cur == nil or cur.t ~= k then
            flush ()
            cur = { t = k, o = b.o, h = b.h, l = b.l, c = b.c, n = 1 }
        else
            cur.h, cur.l, cur.c, cur.n = math.max (cur.h, b.h), math.min (cur.l, b.l), b.c, cur.n + 1
        end
    end
    flush ()
    return out
end

function M.prepare (input, cfg)
    local d = cfg.data
    local errs, warns = {}, {}
    local res = { ok = false, errors = errs, warnings = warns, m1 = {}, m5 = {}, m5_source = "none", stats = {} }
    if type (input) ~= "table" then add (errs, "INPUT_INVALID"); return res end
    local now = input.now
    if not util.finite (now) or math.floor (now) ~= now then add (errs, "NOW_INVALID"); return res end

    local closed, st = M.closed_candles (input.m1, d.m1_period, now, cfg, "M1_", errs, warns)
    res.stats.m1 = st
    if #errs > 0 then return res end
    if #closed == 0 then add (errs, "M1_NO_CLOSED_CANDLES"); return res end

    -- contiguous segment ending at the newest closed candle
    local P, start, resets = d.m1_period, 1, 0
    for i = #closed, 2, -1 do
        local missing = (closed[i].t - closed[i - 1].t) / P - 1
        if missing > d.max_gap_candles then start = i; resets = 1; break end
    end
    if resets > 0 then add (warns, "M1_HISTORY_RESET_AT_GAP") end
    local first = math.max (start, #closed - d.m1_window + 1)
    local win = util.slice (closed, first, #closed)
    local span = (win[#win].t - win[1].t) / P + 1
    local missing = span - #win
    res.stats.window, res.stats.missing = #win, missing
    if missing > 0 then add (warns, "M1_MISSING_CANDLES") end
    if missing / span > d.max_missing_ratio then add (errs, "M1_TOO_MANY_MISSING") end
    if #win < d.min_m1_bars then add (errs, "INSUFFICIENT_HISTORY") end
    local age = now - (win[#win].t + P)
    res.stats.staleness_sec = age
    if age >= d.max_staleness_sec then add (errs, "STALE_DATA") end
    res.m1 = win

    -- M5 context: provided or aggregated from clock-aligned M1 buckets
    local P5 = d.m5_period
    local agg = M.aggregate_m5 (win, now, cfg)
    local m5 = agg
    res.m5_source = "aggregate"
    -- bound the M5 history and check alignment with `now`
    if #m5 > 200 then m5 = util.slice (m5, #m5 - 199, #m5) end
    res.m5 = m5
    local expected = now - now % P5 - P5
    if #m5 == 0 or m5[#m5].t ~= expected then add (errs, "M5_STALE_OR_MISALIGNED") end
    for i = 2, #m5 do
        if m5[i].t - m5[i - 1].t ~= P5 then add (warns, "M5_GAP"); break end
    end
    if #m5 < d.min_m5_bars then add (errs, "M5_INSUFFICIENT") end
    table.sort (errs); table.sort (warns)
    res.ok = #errs == 0
    return res
end

return M
end
__mods["regime_detection"] = function ()
-- =====================================================================
--  MODULE 2 — regime_detection
--
--  raw_at(f, i, cfg) -> regime, metrics     (uses features at index <= i)
--  detect(f, cfg)    -> { regime, raw, direction, sub, metrics }
--
--  Regimes (priority order):
--    HIGH_VOL  ATR/baseline >= hv_atr_ratio
--    LOW_VOL   ATR/baseline <= lv_atr_ratio
--    UNSTABLE  >= whipsaw_crosses EMA9/EMA21 crosses in whipsaw_lookback (sub WHIPSAW)
--    TRENDING  ER >= er_trend, |EMA50 slope| >= slope_min, EMA9/21/50 stacked
--              in the slope direction and close on that side of EMA50
--    RANGING   ER <= er_range and |slope| < slope_min
--    UNSTABLE  otherwise (sub UNCLEAR)
--  Confirmation (stateless, no repaint): the confirmed regime is the raw
--  regime of the newest closed candle only if the raw regime of the last
--  confirm_bars candles agrees; HIGH_VOL is confirmed immediately
--  (safety). Otherwise UNSTABLE/TRANSITION.
-- =====================================================================
local M = {}

local function slope_at (f, i)
    local a, b, atr = f.ema_s[i], f.ema_s[i - 5], f.atr[i]
    if a == nil or b == nil or atr == nil or atr <= 0 then return nil end
    return (a - b) / (5 * atr)
end
M.slope_at = slope_at

function M.crosses (f, i, n)
    local cnt, prev = 0, nil
    for j = i - n + 1, i do
        local a, b = f.ema_f[j], f.ema_m[j]
        if a ~= nil and b ~= nil and a ~= b then
            local s = a > b and 1 or -1
            if prev ~= nil and s ~= prev then cnt = cnt + 1 end
            prev = s
        end
    end
    return cnt
end

function M.raw_at (f, i, cfg)
    local r = cfg.regime
    local atr, base, er = f.atr[i], f.atr_base[i], f.er[i]
    local slope = slope_at (f, i)
    local ef, em, es, c = f.ema_f[i], f.ema_m[i], f.ema_s[i], f.C[i]
    if atr == nil or base == nil or base <= 0 or er == nil or slope == nil or ef == nil or em == nil or es == nil then
        return "UNSTABLE", { sub = "NO_DATA" }
    end
    local m = { atr_ratio = atr / base, er = er, slope = slope, crosses = M.crosses (f, i, cfg.regime.whipsaw_lookback) }
    if m.atr_ratio >= r.hv_atr_ratio then return "HIGH_VOL", m end
    if m.atr_ratio <= r.lv_atr_ratio then return "LOW_VOL", m end
    if m.crosses >= r.whipsaw_crosses then m.sub = "WHIPSAW"; return "UNSTABLE", m end
    local up = ef > em and em > es and c > es and slope >= r.slope_min
    local dn = ef < em and em < es and c < es and slope <= -r.slope_min
    if er >= r.er_trend and (up or dn) then m.dir = up and 1 or -1; return "TRENDING", m end
    if er <= r.er_range and math.abs (slope) < r.slope_min then return "RANGING", m end
    m.sub = "UNCLEAR"
    return "UNSTABLE", m
end

function M.detect (f, cfg)
    local n = f.n
    local raw, m = M.raw_at (f, n, cfg)
    local out = { raw = raw, metrics = m, direction = m.dir or 0, sub = m.sub }
    if raw == "HIGH_VOL" then out.regime = "HIGH_VOL"; return out end
    local agree = true
    for k = 1, cfg.regime.confirm_bars - 1 do
        local r2, m2 = M.raw_at (f, n - k, cfg)
        if r2 ~= raw or (raw == "TRENDING" and m2.dir ~= m.dir) then agree = false; break end
    end
    if agree then out.regime = raw
    else out.regime, out.sub, out.direction = "UNSTABLE", "TRANSITION", 0 end
    return out
end

return M
end
__mods["trend_context"] = function ()
-- =====================================================================
--  MODULE 3 — trend_context
--
--  m5_bias(f5, cfg) -> { bias = 1|-1|0, strength 0..1, available }
--     bias  1: EMA_fast > EMA_slow, slope of EMA_slow (3 bars, in M5 ATR) > 0
--              and close > EMA_slow.  -1 mirrored.  0 otherwise.
--  analyze(f, f5, cfg) -> {
--     m1_dir      1|-1|0  EMA9/21/50 stack with matching EMA50 slope sign
--     m1_strength 0..1    stack spread + slope
--     consistency 0..1    share of the last 10 closes on the m1_dir side of EMA21
--     structure   1|-1|0  last two confirmed swings: HH+HL / LH+LL
--     reversal    { [1]=bool, [-1]=bool } structure break against side s:
--                 EMA21 on side s of EMA50 but close beyond the last swing on the other side
--     m5          m5_bias(...)
--     conflict    true when M1 direction and M5 bias are opposite
--  }
--  M5 is CONTEXT: it adds/removes score and only blocks continuation
--  setups when strongly opposite (see signal_engine).
-- =====================================================================
local util = require ("util")
local M = {}

function M.m5_bias (f5, cfg)
    local n = f5.n
    local out = { bias = 0, strength = 0, available = false }
    local ef, es, es3, atr, c = f5.ema_f[n], f5.ema_s[n], f5.ema_s[n - 3], f5.atr[n], f5.C[n]
    if ef == nil or es == nil or es3 == nil or atr == nil or atr <= 0 then return out end
    out.available = true
    local slope = (es - es3) / (3 * atr)
    out.slope, out.spread = slope, (ef - es) / atr
    if ef > es and slope > 0 and c > es then out.bias = 1
    elseif ef < es and slope < 0 and c < es then out.bias = -1 end
    if out.bias ~= 0 then
        out.strength = 0.5 * util.unit (math.abs (out.spread) / 1.0) + 0.5 * util.unit (math.abs (slope) / 0.1)
    end
    return out
end

function M.structure (f)
    local hs, ls = f.swing_highs, f.swing_lows
    if #hs < 2 or #ls < 2 then return 0 end
    local hh, hl = hs[#hs].price > hs[#hs - 1].price, ls[#ls].price > ls[#ls - 1].price
    local lh, ll = hs[#hs].price < hs[#hs - 1].price, ls[#ls].price < ls[#ls - 1].price
    if hh and hl then return 1 elseif lh and ll then return -1 end
    return 0
end

function M.analyze (f, f5, cfg)
    local n = f.n
    local ef, em, es, c, atr = f.ema_f[n], f.ema_m[n], f.ema_s[n], f.C[n], f.atr[n]
    local es5 = f.ema_s[n - 5]
    local out = { m1_dir = 0, m1_strength = 0, consistency = 0, structure = M.structure (f), reversal = { [1] = false, [-1] = false } }
    if ef and em and es and es5 and atr and atr > 0 then
        local slope = (es - es5) / (5 * atr)
        out.slope = slope
        if ef > em and em > es and slope > 0 then out.m1_dir = 1
        elseif ef < em and em < es and slope < 0 then out.m1_dir = -1 end
        if out.m1_dir ~= 0 then
            out.m1_strength = 0.5 * util.unit (math.abs (ef - es) / atr / 1.5)
                + 0.5 * util.unit (math.abs (slope) / (3 * math.max (cfg.regime.slope_min, 1e-4)))
        end
        local side, k = (out.m1_dir ~= 0) and out.m1_dir or ((em > es) and 1 or -1), 0
        for i = n - 9, n do
            if f.ema_m[i] and (f.C[i] - f.ema_m[i]) * side > 0 then k = k + 1 end
        end
        out.consistency = k / 10
        local lo, hi = f.swing_lows[#f.swing_lows], f.swing_highs[#f.swing_highs]
        out.reversal[1] = em > es and lo ~= nil and c < lo.price
        out.reversal[-1] = em < es and hi ~= nil and c > hi.price
    end
    out.m5 = f5 and M.m5_bias (f5, cfg) or { bias = 0, strength = 0, available = false }
    out.conflict = out.m1_dir ~= 0 and out.m5.bias ~= 0 and out.m1_dir ~= out.m5.bias
    return out
end

return M
end
__mods["momentum_analysis"] = function ()
-- =====================================================================
--  MODULE 4 — momentum_analysis
--
--  Two non-redundant measures:
--    * MACD histogram / ATR  -> direction, strength, acceleration
--    * RSI(14)               -> exhaustion levels and divergence only
--  analyze(f, cfg) -> {
--     dir        sign of hist[n]
--     strength   0..1   |hist| / ATR, saturating at hist_strong_atr
--     accel      +1 hist rising two bars in a row, -1 falling, 0 mixed
--     rsi        RSI[n]
--     side[s]    for s = 1 (CALL) / -1 (PUT):
--        aligned      hist on side s
--        accelerating hist moving toward s on the last two bars
--        decelerating |hist| on side s shrinking two bars in a row
--        turning      hist moved toward s on the last bar (any sign)
--        exhausted    RSI beyond the exhaust level on side s, or
--                     >= exhaust_run consecutive candles toward s, or
--                     climax body >= climax_body_atr * ATR toward s
--        divergence   divergence AGAINST s (bearish div for CALL):
--                     newest two confirmed swing highs make a higher high
--                     while RSI at those pivots falls by >= div_min_rsi;
--                     newest pivot no older than div_max_age bars
--  }
-- =====================================================================
local util = require ("util")
local M = {}

local function divergence (swings, rsi, n, sgn, cfg)
    local k = #swings
    if k < 2 then return false end
    local a, b = swings[k - 1], swings[k]
    if n - b.i > cfg.momentum.div_max_age then return false end
    local ra, rb = rsi[a.i], rsi[b.i]
    if ra == nil or rb == nil then return false end
    return sgn * (b.price - a.price) > 0 and sgn * (ra - rb) >= cfg.momentum.div_min_rsi
end
M.divergence = divergence

function M.analyze (f, cfg)
    local n, mc = f.n, cfg.momentum
    local h0, h1, h2 = f.hist[n], f.hist[n - 1], f.hist[n - 2]
    local atr, rsi = f.atr[n - 1] or f.atr[n], f.rsi[n]
    local out = { available = false, side = {} }
    if h0 == nil or h1 == nil or h2 == nil or atr == nil or atr <= 0 or rsi == nil then return out end
    out.available, out.rsi = true, rsi
    out.dir = util.sign (h0)
    out.hist_atr = h0 / atr
    out.strength = util.unit (math.abs (h0) / atr / mc.hist_strong_atr)
    out.accel = (h0 > h1 and h1 > h2) and 1 or ((h0 < h1 and h1 < h2) and -1 or 0)
    for _, s in ipairs ({ 1, -1 }) do
        local x = {}
        x.aligned = s * h0 > 0
        x.accelerating = s * (h0 - h1) > 0 and s * (h1 - h2) > 0
        x.decelerating = x.aligned and s * h1 > 0 and s * (h0 - h1) < 0 and s * (h1 - h2) < 0
        x.turning = s * (h0 - h1) > 0
        local run = 0
        for i = n, math.max (1, n - mc.exhaust_run), -1 do
            if s * (f.C[i] - f.O[i]) > 0 then run = run + 1 else break end
        end
        local body = s * (f.C[n] - f.O[n])
        x.run = run
        x.exhausted = (s == 1 and rsi >= mc.exhaust_rsi_high) or (s == -1 and rsi <= mc.exhaust_rsi_low)
            or run >= mc.exhaust_run or body >= mc.climax_body_atr * atr
        -- against CALL: bearish divergence on swing highs; against PUT: bullish on swing lows
        if s == 1 then x.divergence = divergence (f.swing_highs, f.rsi, n, 1, cfg)
        else x.divergence = divergence (f.swing_lows, f.rsi, n, -1, cfg) end
        out.side[s] = x
    end
    return out
end

return M
end
__mods["price_action"] = function ()
-- =====================================================================
--  MODULE 5 — price_action
--
--  analyze(f, cfg) -> { side = { [1] = P, [-1] = P }, structure_levels }
--  Everything is measured on CLOSED candles n (newest) and n-1, in the
--  frame of side s: PUT mirrors prices (x -> -x, high <-> low), so one
--  rule set serves both sides. ATR reference = ATR[n-1] (before the
--  trigger candle, so a large candle cannot inflate its own threshold).
--
--  Pattern definitions (CALL frame; points used by the scorer):
--   ENGULF (20)      n bullish, n-1 bearish, C[n] >= O[n-1], O[n] <= C[n-1],
--                    body[n] >= 1.1 body[n-1], body[n] >= engulf_min_body_atr ATR,
--                    body[n-1] >= 0.1 ATR, close location >= 0.65
--   REJECTION_CONF (18) n-1 has lower wick >= pin_wick_ratio of range, range
--                    >= 0.5 ATR; n bullish, closes above n-1 body, cl.loc >= 0.6
--   FAILED_BREAK (17) low[n] < support - buffer ATR, close[n] > support, cl.loc >= 0.6
--   BREAKOUT (16)    nearest resistance R above close[n-1]: close[n] > R + buffer ATR,
--                    bullish, body >= 0.5 range, cl.loc >= strong_close,
--                    body <= max_trigger_body_atr ATR
--   REJECTION (15)   n: lower wick >= pin_wick_ratio range, upper wick <= 0.25
--                    range, range >= 0.5 ATR, cl.loc >= 0.6
--   STRONG_CLOSE (12) bullish, body >= 0.55 range, cl.loc >= 0.75,
--                    0.35 <= body/ATR <= max_trigger_body_atr
--  Levels: confirmed swing pivots (indicators.pivots) + range extremes of
--  the range_lookback candles before n.
-- =====================================================================
local util = require ("util")
local M = {}

M.POINTS = { ENGULF = 20, REJECTION_CONF = 18, FAILED_BREAK = 17, BREAKOUT = 16, REJECTION = 15, STRONG_CLOSE = 12 }

local function frame (f, s)
    local H, L, O, C = f.H, f.L, f.O, f.C
    if s == 1 then
        return function (i) return H[i] end, function (i) return L[i] end,
               function (i) return O[i] end, function (i) return C[i] end
    end
    return function (i) return -L[i] end, function (i) return -H[i] end,
           function (i) return -O[i] end, function (i) return -C[i] end
end

function M.geometry (hi, lo, op, cl, i)
    local h, l, o, c = hi (i), lo (i), op (i), cl (i)
    local rng = math.max (h - l, 1e-9)
    return { rng = rng, body = math.abs (c - o), bull = c > o, bear = c < o,
             upw = h - math.max (c, o), loww = math.min (c, o) - l, cpos = (c - l) / rng }
end

function M.analyze_side (f, s, cfg)
    local pa, en = cfg.price_action, cfg.entry
    local n = f.n
    local atr = f.atr[n - 1]
    local hi, lo, op, cl = frame (f, s)
    local g, g1 = M.geometry (hi, lo, op, cl, n), M.geometry (hi, lo, op, cl, n - 1)
    local c, c1 = cl (n), cl (n - 1)
    local out = { geom = g, patterns = {}, best = "NONE", points = 0 }

    -- levels in this frame: ahead (obstacles in trade direction) and behind
    local ahead, behind = {}, {}
    local A = s == 1 and f.swing_highs or f.swing_lows
    local B = s == 1 and f.swing_lows or f.swing_highs
    for _, p in ipairs (A) do ahead[#ahead + 1] = s * p.price end
    for _, p in ipairs (B) do behind[#behind + 1] = s * p.price end
    local rhi, rlo = -math.huge, math.huge
    for i = math.max (1, n - pa.range_lookback), n - 1 do rhi = math.max (rhi, hi (i)); rlo = math.min (rlo, lo (i)) end
    ahead[#ahead + 1], behind[#behind + 1] = rhi, rlo
    out.range_hi, out.range_lo = rhi, rlo
    out.range_pos = (rhi > rlo) and util.unit ((c - rlo) / (rhi - rlo)) or 0.5

    -- room to the nearest obstacle ahead of the close
    local room = en.room_cap_atr
    for _, x in ipairs (ahead) do if x > c then room = math.min (room, (x - c) / atr) end end
    out.room_atr = room
    -- nearest level behind the close (support in CALL frame)
    local sup = nil
    for _, x in ipairs (behind) do if x <= c and (sup == nil or x > sup) then sup = x end end
    out.support = sup
    out.at_support = sup ~= nil and math.min (lo (n), lo (n - 1)) <= sup + pa.level_touch_atr * atr
    out.at_range_low = math.min (lo (n), lo (n - 1)) <= rlo + pa.level_touch_atr * atr

    local function take (name)
        out.patterns[#out.patterns + 1] = name
        if M.POINTS[name] > out.points then out.points, out.best = M.POINTS[name], name end
    end
    if g.bull and g1.bear and c >= op (n - 1) and op (n) <= c1 and g.body >= 1.1 * g1.body
       and g.body >= pa.engulf_min_body_atr * atr and g1.body >= 0.1 * atr and g.cpos >= 0.65 then take ("ENGULF") end
    if g1.loww >= pa.pin_wick_ratio * g1.rng and g1.rng >= 0.5 * atr and g.bull
       and c > math.max (op (n - 1), c1) and g.cpos >= 0.6 then take ("REJECTION_CONF") end
    -- failed break: sweep of the most recent level behind (swing or range low) and reclaim
    local swept = nil
    for _, x in ipairs (behind) do
        if lo (n) < x - pa.breakout_buffer_atr * atr and c > x and (swept == nil or x > swept) then swept = x end
    end
    if swept ~= nil and g.cpos >= 0.6 then take ("FAILED_BREAK"); out.swept_level = swept end
    -- breakout through the nearest level that was above the previous close
    local lvl = nil
    for _, x in ipairs (ahead) do if x >= c1 and (lvl == nil or x < lvl) then lvl = x end end
    if lvl ~= nil and c > lvl + pa.breakout_buffer_atr * atr and g.bull and g.body >= 0.5 * g.rng
       and g.cpos >= pa.strong_close and g.body <= en.max_trigger_body_atr * atr then
        take ("BREAKOUT"); out.breakout_level = lvl
    end
    if g.loww >= pa.pin_wick_ratio * g.rng and g.upw <= 0.25 * g.rng and g.rng >= 0.5 * atr and g.cpos >= 0.6 then
        take ("REJECTION") end
    if g.bull and g.body >= 0.55 * g.rng and g.cpos >= 0.75 and g.body >= 0.35 * atr
       and g.body <= en.max_trigger_body_atr * atr then take ("STRONG_CLOSE") end

    local run = 0
    for i = n, 1, -1 do if cl (i) > op (i) then run = run + 1 else break end end
    out.run = run
    out.wick_against = g.upw / g.rng
    return out
end

function M.analyze (f, cfg)
    return { side = { [1] = M.analyze_side (f, 1, cfg), [-1] = M.analyze_side (f, -1, cfg) } }
end

return M
end
__mods["entry_timing"] = function ()
-- =====================================================================
--  MODULE 6 — entry_timing
--
--  analyze_side(f, s, pa, prof, cfg) -> { [SETUP] = E, ... } for the
--  setups allowed by the profile. E = {
--     present   setup conditions met on the closed candles
--     trigger   price-action pattern used
--     ext       extension in ATR from the setup's reference (ext_ref):
--               PULLBACK -> EMA9 (the mean price pulled back to; FAST_ENTRY_AUDIT §2),
--               TREND -> EMA21, BREAKOUT -> the broken level, RANGE -> EMA21 (info)
--     room      ATR to the nearest obstacle ahead
--     late      true when the move is already extended (late_why says why)
--     no_room   room < profile.min_room_atr
--     quality   0..1 timing quality (room beyond minimum + closeness to EMA21)
--  }
--  The entry is the OPEN of the candle after the newest closed candle n;
--  nothing here reads a candle that has not closed.
--
--  Setup rules (CALL frame, PUT mirrored):
--   PULLBACK_CONTINUATION  EMA21 > EMA50 and EMA50 slope > 0; within the
--      pullback_lookback candles before n at least one counter candle,
--      a low touching EMA9 + pullback_zone_atr ATR, and no close below
--      EMA50; candle n triggers (ENGULF/REJECTION*/FAILED_BREAK/
--      STRONG_CLOSE), is bullish and closes above EMA9.
--   TREND_CONTINUATION  EMA9 > EMA21 > EMA50, slope >= slope_min, trigger
--      ENGULF/STRONG_CLOSE/BREAKOUT, close > EMA9 and close[n-1] > EMA9.
--   BREAKOUT_CONFIRMATION  BREAKOUT pattern on candle n; late when the close
--      is more than entry.breakout_max_ext_atr beyond the broken level.
--   RANGE_REJECTION  low of n or n-1 at support / range low, trigger
--      REJECTION*/ENGULF/FAILED_BREAK, RSI (side frame) at n-1 <= 50,
--      close in the lower 60% of the range.
-- =====================================================================
local util = require ("util")
local price_action = require ("price_action")
local M = {}

local PB_TRIG = { ENGULF = true, REJECTION_CONF = true, REJECTION = true, FAILED_BREAK = true, STRONG_CLOSE = true }
local TC_TRIG = { ENGULF = true, STRONG_CLOSE = true, BREAKOUT = true }
local RR_TRIG = { REJECTION_CONF = true, REJECTION = true, ENGULF = true, FAILED_BREAK = true }

local function pick (pa, allowed)
    local best, pts = nil, -1
    for _, p in ipairs (pa.patterns) do
        local v = price_action.POINTS[p]
        if allowed[p] and v > pts then best, pts = p, v end
    end
    return best
end

function M.analyze_side (f, s, pa, prof, cfg)
    local en, n = cfg.entry, f.n
    local atr = f.atr[n - 1]
    local e9, e21, e50 = s * f.ema_f[n], s * f.ema_m[n], s * f.ema_s[n]
    local es5 = f.ema_s[n - 5]
    local slope = s * (f.ema_s[n] - es5) / (5 * f.atr[n])
    local c, c1 = s * f.C[n], s * f.C[n - 1]
    local g = pa.geom
    local ext21 = (c - e21) / atr
    local move3 = (c - s * f.O[n - 2]) / atr
    local out = {}

    for _, setup in ipairs (prof.setups) do
        local E = { present = false, ext = ext21, ext_ref = "EMA21", room = pa.room_atr, late = false }
        local max_ext = prof.max_ext_atr
        if setup == "PULLBACK_CONTINUATION" then
            local touched, counter, inside = false, false, true
            for i = n - en.pullback_lookback, n - 1 do
                local lo = (s == 1) and f.L[i] or -f.H[i]
                if lo <= s * f.ema_f[i] + en.pullback_zone_atr * atr then touched = true end
                if s * (f.C[i] - f.O[i]) < 0 then counter = true end
                if s * f.C[i] <= s * f.ema_s[i] then inside = false end
            end
            E.trigger = pick (pa, PB_TRIG)
            E.present = e21 > e50 and slope > 0 and touched and counter and inside
                and E.trigger ~= nil and g.bull and c > e9
            E.ext, E.ext_ref = (c - e9) / atr, "EMA9"
        elseif setup == "TREND_CONTINUATION" then
            E.trigger = pick (pa, TC_TRIG)
            E.present = e9 > e21 and e21 > e50 and slope >= cfg.regime.slope_min and E.trigger ~= nil
                and c > e9 and c1 > s * f.ema_f[n - 1]
        elseif setup == "BREAKOUT_CONFIRMATION" then
            E.trigger = util.contains (pa.patterns, "BREAKOUT") and "BREAKOUT" or nil
            E.present = E.trigger ~= nil
            if pa.breakout_level then E.ext, E.ext_ref = (c - pa.breakout_level) / atr, "BREAKOUT_LEVEL" end
            max_ext = en.breakout_max_ext_atr
        elseif setup == "RANGE_REJECTION" then
            local r1 = f.rsi[n - 1]
            r1 = (s == 1) and r1 or (r1 and 100 - r1)
            E.trigger = pick (pa, RR_TRIG)
            E.present = (pa.at_support or pa.at_range_low) and E.trigger ~= nil and r1 ~= nil and r1 <= 50
                and pa.range_pos <= 0.6
        end
        -- timing
        if setup == "RANGE_REJECTION" then
            if pa.range_pos > 0.6 then E.late, E.late_why = true, "RANGE_MIDDLE" end
        elseif E.ext > max_ext then E.late, E.late_why = true, "EXTENDED_FROM_" .. E.ext_ref end
        if not E.late and move3 > en.late_move_atr then E.late, E.late_why = true, "MOVE_ALREADY_MADE" end
        if not E.late and g.body > en.max_trigger_body_atr * atr then E.late, E.late_why = true, "TRIGGER_TOO_LARGE" end
        E.no_room = pa.room_atr < prof.min_room_atr
        E.quality = 0.5 * util.unit ((pa.room_atr - prof.min_room_atr) / 1.5)
            + 0.5 * (1 - util.unit (math.max (E.ext, 0) / math.max (max_ext, 0.1)))
        out[setup] = E
    end
    return out
end

return M
end
__mods["volatility_filter"] = function ()
-- =====================================================================
--  MODULE 7 — volatility_filter
--
--  evaluate(f, cfg) -> { ok, reasons = {codes}, metrics, spread }
--  Hard rejections (any -> WAIT), all measured on closed candles:
--    ABNORMAL_RANGE    range[n] > abnormal_range_atr * ATR[n-1]
--    VOL_EXPANSION     ATR[n] / ATR[n-k] > expansion_ratio (k = expansion_lookback)
--    LOW_INFORMATION   ATR[n] < min_atr_price (USD), or more than
--                      max_flat_candles of the last flat_lookback candles
--                      have range < flat_range_atr * ATR (frozen/thin feed)
--    NOISE             ER[n] < noise_er and the mean wick share of the
--                      last 10 candles > noise_wick_share
--  Spread / execution data is NOT available from candles; `spread` is
--  reported as "NOT_AVAILABLE" rather than estimated.
-- =====================================================================
local M = {}

function M.evaluate (f, cfg)
    local v, n = cfg.volatility, f.n
    local atr, atr_prev, atr_k = f.atr[n], f.atr[n - 1], f.atr[n - v.expansion_lookback]
    local out = { ok = true, reasons = {}, metrics = {}, spread = "NOT_AVAILABLE" }
    local function reject (code) out.ok = false; out.reasons[#out.reasons + 1] = code end
    if atr == nil or atr_prev == nil or atr_k == nil or atr_prev <= 0 or atr_k <= 0 then
        reject ("VOLATILITY_UNMEASURABLE"); return out
    end
    local range = f.H[n] - f.L[n]
    out.metrics.range_atr = range / atr_prev
    out.metrics.expansion = atr / atr_k
    if range > v.abnormal_range_atr * atr_prev then reject ("ABNORMAL_RANGE") end
    if atr / atr_k > v.expansion_ratio then reject ("VOL_EXPANSION") end
    local flat = 0
    for i = n - v.flat_lookback + 1, n do
        if f.H[i] - f.L[i] < v.flat_range_atr * atr then flat = flat + 1 end
    end
    out.metrics.flat = flat
    if atr < v.min_atr_price or flat > v.max_flat_candles then reject ("LOW_INFORMATION") end
    local wick = 0
    for i = n - 9, n do
        local r = f.H[i] - f.L[i]
        wick = wick + (r > 0 and (r - math.abs (f.C[i] - f.O[i])) / r or 1)
    end
    wick = wick / 10
    out.metrics.wick_share = wick
    local er = f.er[n] or 0
    if er < v.noise_er and wick > v.noise_wick_share then reject ("NOISE") end
    return out
end

return M
end
__mods["adaptive_profile"] = function ()
-- =====================================================================
--  MODULE 8 — adaptive_profile
--
--  select(regime, cfg) -> profile
--    profile = { name, tradable, setups = {...}, min_score, min_room_atr,
--                max_ext_atr, reason }
--  Deterministic map from the CONFIRMED regime to an explicit, bounded
--  parameter set taken from cfg.profiles (validated by config.lua):
--    TRENDING -> "TRENDING" profile (pullback / trend continuation /
--                breakout confirmation)
--    RANGING  -> "RANGING" profile (range rejection / breakout confirmation)
--    HIGH_VOL, LOW_VOL, UNSTABLE -> "DEFENSIVE": nothing tradable -> WAIT
--  No learning, no dependence on recent wins/losses. The profile min_score
--  can never be below scoring.global_min_score (enforced here as well).
-- =====================================================================
local util = require ("util")
local M = {}

function M.select (regime, cfg)
    local p = cfg.profiles[regime.regime]
    if p == nil then
        return { name = "DEFENSIVE", tradable = false, setups = {},
                 reason = "DEFENSIVE_" .. regime.regime .. (regime.sub and ("_" .. regime.sub) or "") }
    end
    return {
        name = regime.regime, tradable = true, setups = util.deepcopy (p.setups),
        min_score = math.max (p.min_score, cfg.scoring.global_min_score),
        min_room_atr = p.min_room_atr, max_ext_atr = p.max_ext_atr,
    }
end

return M
end
__mods["signal_engine"] = function ()
-- =====================================================================
--  MODULE 9 — signal_engine (scoring + decision)
--
--  score_setup(ctx, s, setup, E) -> { score, components, penalties, gates }
--  decide(ctx) -> { decision = "CALL"|"PUT"|"WAIT", reasons, side = {...} }
--
--  ctx = { cfg, regime, profile, trend, momentum, pa, entry, vol }
--
--  SCORE (0..100, integer). It measures how strongly the measured
--  conditions agree. It is NOT a win probability (it has not been
--  calibrated on verified market data).
--    context    0..25  continuation: M1 direction on side s (10) + 8 x M1
--                      strength + 7 x consistency.  range setups: 15 x (1 -
--                      ER/er_trend) + 10 if swing structure not against s
--    momentum   0..20  continuation: aligned 8 + 6 x strength + accelerating 6
--                      (or turning 3).  range rejection: turning 10 + RSI(n-1)
--                      in side frame <= 40: 5 + aligned 5
--    price act. 0..20  pattern points of the trigger (price_action.POINTS)
--    timing     0..20  20 x entry quality
--    m5         0..10  bias on side s: 6 + 4 x strength; neutral: 4; opposite: 0
--    regime     0..5   5 when the confirmed regime supports side s
--    penalties         M5 opposite, divergence against s, decelerating
--                      momentum, adverse wick >= 35% of the trigger candle
--  GATES (any -> the setup cannot fire): SETUP_NOT_PRESENT, EXHAUSTION,
--    STRUCTURE_BREAK, LATE_ENTRY_<why>, NO_ROOM, M5_STRONG_OPPOSITE,
--    MOMENTUM_CONFLICT, LOW_SCORE.
--  DECISION: WAIT unless exactly one side has a passing setup AND it beats
--    the other side's best present setup by >= scoring.min_margin.
-- =====================================================================
local util = require ("util")
local price_action = require ("price_action")

local M = {}

local CONTINUATION = { PULLBACK_CONTINUATION = true, TREND_CONTINUATION = true }

function M.score_setup (ctx, s, setup, E)
    local cfg, tr, mo = ctx.cfg, ctx.trend, ctx.momentum
    local ms, pa = mo.side[s], ctx.pa.side[s]
    local sc = cfg.scoring
    local range_mode = setup == "RANGE_REJECTION" or (setup == "BREAKOUT_CONFIRMATION" and ctx.regime.regime == "RANGING")
    local comp, pen, gates = {}, {}, {}

    if range_mode then
        local er = ctx.regime.metrics.er or 0
        comp.context = 15 * (1 - util.unit (er / cfg.regime.er_trend)) + ((tr.structure ~= -s) and 10 or 0)
    else
        comp.context = (tr.m1_dir == s) and (10 + 8 * tr.m1_strength + 7 * tr.consistency) or 0
    end
    if setup == "RANGE_REJECTION" then
        local r1 = ctx.f.rsi[ctx.f.n - 1]
        r1 = (s == 1) and r1 or (100 - r1)
        comp.momentum = (ms.turning and 10 or 0) + ((r1 <= 40) and 5 or 0) + (ms.aligned and 5 or 0)
    else
        comp.momentum = (ms.aligned and (8 + 6 * mo.strength) or 0)
            + (ms.accelerating and 6 or (ms.turning and 3 or 0))
    end
    comp.price_action = E.trigger and price_action.POINTS[E.trigger] or 0
    comp.timing = 20 * (E.quality or 0)
    local m5 = tr.m5
    comp.m5 = (m5.bias == s) and (6 + 4 * m5.strength) or ((m5.bias == 0) and 4 or 0)
    local rdir = ctx.regime.direction or 0
    comp.regime = ((ctx.regime.regime == "TRENDING" and rdir == s) or ctx.regime.regime == "RANGING") and 5 or 0

    if m5.bias == -s then pen.m5_conflict = sc.m5_conflict_penalty end
    if ms.divergence then pen.divergence = sc.divergence_penalty end
    if ms.decelerating then pen.deceleration = sc.decel_penalty end
    if pa.wick_against >= 0.35 then pen.adverse_wick = sc.wick_penalty end

    local total, ptotal = 0, 0
    for _, k in ipairs (util.sorted_keys (comp)) do total = total + comp[k] end
    for _, k in ipairs (util.sorted_keys (pen)) do ptotal = ptotal + pen[k] end
    local score = math.floor (util.clamp (total - ptotal, 0, 100) + 0.5)

    local function gate (g) gates[#gates + 1] = g end
    if not E.present then gate ("SETUP_NOT_PRESENT") end
    if ms.exhausted then gate ("EXHAUSTION") end
    if (CONTINUATION[setup] or setup == "BREAKOUT_CONFIRMATION") and tr.reversal[s] then gate ("STRUCTURE_BREAK") end
    if E.late then gate ("LATE_ENTRY_" .. E.late_why) end
    if E.no_room then gate ("NO_ROOM") end
    if (CONTINUATION[setup] or setup == "BREAKOUT_CONFIRMATION") and m5.bias == -s and m5.strength >= sc.m5_block_strength then
        gate ("M5_STRONG_OPPOSITE") end
    local mom_ok
    if setup == "PULLBACK_CONTINUATION" or setup == "RANGE_REJECTION" then mom_ok = ms.turning
    elseif setup == "TREND_CONTINUATION" then mom_ok = ms.aligned and not ms.decelerating
    else mom_ok = ms.aligned end
    if not mom_ok then gate ("MOMENTUM_CONFLICT") end
    if score < ctx.profile.min_score then gate ("LOW_SCORE") end

    return { setup = setup, score = score, trigger = E.trigger, components = comp, penalties = pen, gates = gates,
             present = E.present, passed = #gates == 0, ext = E.ext, room = E.room }
end

--- evaluates every allowed setup on one side and picks the best
function M.evaluate_side (ctx, s)
    local list = {}
    for _, setup in ipairs (ctx.profile.setups) do
        list[#list + 1] = M.score_setup (ctx, s, setup, ctx.entry[s][setup])
    end
    local best_pass, best_present
    for _, r in ipairs (list) do   -- profile order breaks ties deterministically
        if r.passed and (best_pass == nil or r.score > best_pass.score) then best_pass = r end
        if r.present and (best_present == nil or r.score > best_present.score) then best_present = r end
    end
    return { candidates = list, pass = best_pass, best = best_pass or best_present }
end

function M.decide (ctx)
    local call, put = M.evaluate_side (ctx, 1), M.evaluate_side (ctx, -1)
    local out = { side = { [1] = call, [-1] = put }, reasons = {} }
    local cs = call.best and call.best.score or 0
    local ps = put.best and put.best.score or 0
    out.call_score, out.put_score = cs, ps
    if call.pass and put.pass then
        out.decision = "WAIT"; out.reasons[1] = "CONFLICT_BOTH_SIDES"; return out
    end
    local win, other, name = nil, nil, nil
    if call.pass then win, other, name = call.pass, ps, "CALL" elseif put.pass then win, other, name = put.pass, cs, "PUT" end
    if win then
        if win.score - other < ctx.cfg.scoring.min_margin then
            out.decision = "WAIT"; out.reasons[1] = "INSUFFICIENT_MARGIN"; return out
        end
        out.decision, out.selected = name, win
        return out
    end
    out.decision = "WAIT"
    out.reasons[1] = "NO_QUALIFIED_SETUP"
    for _, x in ipairs ({ { "CALL", call }, { "PUT", put } }) do
        local b = x[2].best
        if b then out.reasons[#out.reasons + 1] = x[1] .. ":" .. b.setup .. ":" .. b.gates[1] end
    end
    return out
end

return M
end
__mods["diagnostics"] = function ()
-- =====================================================================
--  MODULE 10 — diagnostics
--
--  build(parts) -> record   structured, explainable evaluation record
--  to_json(v)   -> string   deterministic JSON (sorted keys, fixed number
--                           format) so identical inputs give identical bytes
--  summary(rec) -> string   one-line human-readable summary
-- =====================================================================
local util = require ("util")
local M = {}

M.ENGINE_VERSION = "2.0.0"

local function num (x)
    if x == nil then return nil end
    if math.type and math.type (x) == "integer" then return x end
    if x == math.floor (x) and math.abs (x) < 1e15 then return math.floor (x) end
    return util.round (x, 4)
end


function M.build (p)
    local cfg, dv = p.cfg, p.data
    local r = {
        timestamp = p.now, engine_version = M.ENGINE_VERSION, config_version = cfg.version,
        instrument = cfg.instrument, expiry_sec = 60, time_source = p.time_source or "INPUT",
        decision = p.decision, reasons = p.reasons, call_score = p.call_score or 0, put_score = p.put_score or 0,
        data = {
            valid = dv.ok, errors = dv.errors, warnings = dv.warnings,
            m1_bars = #dv.m1, m5_bars = #dv.m5, m5_source = dv.m5_source,
            missing = dv.stats.missing, staleness_sec = dv.stats.staleness_sec,
            last_closed_t = (#dv.m1 > 0) and dv.m1[#dv.m1].t or nil,
        },
    }
    if p.regime then
        local m = p.regime.metrics or {}
        r.regime = { confirmed = p.regime.regime, raw = p.regime.raw, sub = p.regime.sub, direction = p.regime.direction,
                     atr_ratio = num (m.atr_ratio), er = num (m.er), slope = num (m.slope), ema_crosses = m.crosses }
    end
    r.selected_profile = p.selected and p.selected.setup or (p.profile and not p.profile.tradable and "DEFENSIVE" or "NONE")
    return r
end

return M
end
__mods["main"] = function ()
-- =====================================================================
--  main — public entry point of XAUUSD Smart Entry V2.0.
--
--  local engine = require ("main")
--  local cfg, errs = engine.config (overrides)      -- validated config or nil
--  local res = engine.evaluate (input, cfg)         -- pure, deterministic
--     input = { now = unix_s, m1 = {candles}, m5 = optional, time_source = optional }
--     res   = { decision = "CALL"|"PUT"|"WAIT", call_score, put_score,
--               reasons = {codes}, diagnostics = record }
--  local run = engine.new_runner (cfg)              -- adds the cooldown
--  local res = run:step (input)
--
--  evaluate() only ever looks at candles that closed at or before
--  `now` (validated by data_validation) and keeps no state, so the same
--  input always gives the same output and a past decision can never change.
--  Signal generation only: this module never places trades.
-- =====================================================================
local config            = require ("config")
local data_validation   = require ("data_validation")
local indicators        = require ("indicators")
local regime_detection  = require ("regime_detection")
local trend_context     = require ("trend_context")
local momentum_analysis = require ("momentum_analysis")
local price_action      = require ("price_action")
local entry_timing      = require ("entry_timing")
local volatility_filter = require ("volatility_filter")
local adaptive_profile  = require ("adaptive_profile")
local signal_engine     = require ("signal_engine")
local diagnostics       = require ("diagnostics")

local M = { VERSION = diagnostics.ENGINE_VERSION }

M.config = config.load

local function finish (p)
    p.reasons = p.reasons or {}
    local rec = diagnostics.build (p)
    return { decision = p.decision, call_score = rec.call_score, put_score = rec.put_score,
             reasons = rec.reasons, setup = p.selected and p.selected.setup or nil,
             score = p.selected and p.selected.score or 0, diagnostics = rec }
end

function M.evaluate (input, cfg)
    local p = { cfg = cfg, now = type (input) == "table" and input.now or nil,
                time_source = type (input) == "table" and input.time_source or nil, decision = "WAIT" }
    -- 0. an invalid configuration never produces a signal
    if type (cfg) ~= "table" or not config.validate (cfg) then
        p.cfg = { version = (type (cfg) == "table" and type (cfg.version) == "string") and cfg.version or "INVALID",
                  instrument = "XAUUSD" }
        p.data = { ok = false, errors = { "CONFIG_INVALID" }, warnings = {}, m1 = {}, m5 = {}, stats = {}, m5_source = "none" }
        p.reasons = { "CONFIG_INVALID" }
        return finish (p)
    end
    -- 1. data validation: invalid or insufficient data -> WAIT
    p.data = data_validation.prepare (input, cfg)
    if not p.data.ok then
        p.reasons = { "DATA_INVALID" }
        for _, e in ipairs (p.data.errors) do p.reasons[#p.reasons + 1] = e end
        return finish (p)
    end
    -- 2. features (computed once, shared)
    local f = indicators.compute (p.data.m1, cfg)
    local f5 = indicators.compute_m5 (p.data.m5, cfg)
    -- 3. analysis modules
    p.regime   = regime_detection.detect (f, cfg)
    p.trend    = trend_context.analyze (f, f5, cfg)
    p.momentum = momentum_analysis.analyze (f, cfg)
    p.pa       = price_action.analyze (f, cfg)
    p.vol      = volatility_filter.evaluate (f, cfg)
    p.profile  = adaptive_profile.select (p.regime, cfg)
    if not p.momentum.available or not p.trend.m5.available then
        p.reasons = { "DATA_INVALID", "INDICATORS_UNAVAILABLE" }
        return finish (p)
    end
    if not p.vol.ok then
        p.reasons = { "VOLATILITY_FILTER" }
        for _, r in ipairs (p.vol.reasons) do p.reasons[#p.reasons + 1] = r end
        return finish (p)
    end
    if not p.profile.tradable then
        p.reasons = { p.profile.reason }
        return finish (p)
    end
    -- 4. entry timing per side, then scoring + decision
    local entry = { [1] = entry_timing.analyze_side (f, 1, p.pa.side[1], p.profile, cfg),
                    [-1] = entry_timing.analyze_side (f, -1, p.pa.side[-1], p.profile, cfg) }
    local d = signal_engine.decide ({ cfg = cfg, f = f, regime = p.regime, profile = p.profile, trend = p.trend,
                                      momentum = p.momentum, pa = p.pa, entry = entry, vol = p.vol })
    p.decision, p.reasons, p.sides, p.selected = d.decision, d.reasons, d.side, d.selected
    p.call_score, p.put_score = d.call_score, d.put_score
    return finish (p)
end

return M
end
-- =====================================================================
--  QCS ADAPTER — runs the pure V2.0 engine inside Quadcode Script.
--  Uses only QCS calls already used by the existing QCS scripts and the
--  offline mock (qcs/test/mock_qcs.lua): input, input_group, get_value,
--  make_series / :set, open/high/low/close[i].
--
--  * Every bar, the closed-candle window is rebuilt from [1]..[W]
--    ([0] = the forming candle is NEVER read for the decision), so the
--    decision is a pure function of closed candles: no repaint on ticks.
--  * Timestamps: QCS exposes no timestamp series that has been verified
--    in this repository. Default mode 1 uses the bar index (t = index*60)
--    and reports TIME_SOURCE = "INDEX_PROXY": in that mode M5 buckets
--    are 5-bar groups (not clock aligned) and missing candles cannot be
--    detected. Mode 2 reads a `time` series ONLY if the runtime defines
--    one; otherwise it falls back to INDEX_PROXY and says so.
--  * Cooldown is kept in a make_series written from its own [1] value
--    (the tick-safe pattern of the V3 core).
--  Signal generation only — nothing here can place a trade.
-- =====================================================================
input_group {
    "XAUUSD Smart Entry V2.0",
    v2_window   = input (240, "Closed M1 candles analysed", input.integer, 200, 600),
    v2_cooldown = input (2,   "Cooldown (bars)", input.integer, 0, 20),
    v2_time     = input (1,   "Timestamps: 1 bar index, 2 time series", input.integer, 1, 2)
}

local engine = require ("main")

local function num (s, d)
    local v = get_value (s)
    if v == nil or v ~= v then return d end
    return v
end

v2_bar = make_series ()
v2_bar:set (num (v2_bar[1], 0) + 1)
v2_age = make_series ()

local N = num (v2_bar, 1)
local use_time = v2_time == 2 and type (time) == "table"
TIME_SOURCE = use_time and "TIME_SERIES" or ((v2_time == 2) and "INDEX_PROXY_FALLBACK" or "INDEX_PROXY")
local function stamp (i)
    if use_time then
        local v = (i == 0) and num (time) or num (time[i])
        if v == nil then return nil end
        if v > 1e12 then v = v / 1000 end
        return math.floor (v)
    end
    return (N - i) * 60
end

local cfg = engine.config ({ data = { m1_window = v2_window }, runner = { cooldown_bars = v2_cooldown } })
local m1 = {}
if cfg then
    for i = cfg.data.m1_window, 1, -1 do
        local o, h, l, c, t = num (open[i]), num (high[i]), num (low[i]), num (close[i]), stamp (i)
        if o and h and l and c and t then m1[#m1 + 1] = { t = t, o = o, h = h, l = l, c = c, closed = true } end
    end
end
V2 = engine.evaluate ({ now = stamp (0), m1 = m1, time_source = TIME_SOURCE }, cfg)

-- outputs read by the views
SIG_DIR, SIG_SCORE, SIG_SETUP = 0, 0, ""
CALL_SCORE, PUT_SCORE = V2.call_score, V2.put_score
WAIT_REASON = V2.reasons[1] or ""
local REG = { TRENDING = 1, RANGING = 2, HIGH_VOL = 3, LOW_VOL = 4, UNSTABLE = 5 }
REGIME_CODE = V2.diagnostics.regime and REG[V2.diagnostics.regime.confirmed] or 0
DATA_OK = V2.diagnostics.data.valid

local prev_age = num (v2_age[1], 999)
local dir = (V2.decision == "CALL") and 1 or ((V2.decision == "PUT") and -1 or 0)
if dir ~= 0 and prev_age < v2_cooldown then
    dir, WAIT_REASON = 0, "COOLDOWN"
end
if dir ~= 0 then SIG_DIR, SIG_SCORE, SIG_SETUP = dir, V2.score, V2.setup or "" end
-- setup code for the markers: 1 pullback, 2 trend, 3 breakout, 4 range (signed by side)
local KIND = { PULLBACK_CONTINUATION = 1, TREND_CONTINUATION = 2, BREAKOUT_CONFIRMATION = 3, RANGE_REJECTION = 4 }
SIG_KIND = (KIND[SIG_SETUP] or 0) * SIG_DIR
v2_age:set (SIG_DIR ~= 0 and 0 or prev_age + 1)
-- =====================================================================
--  MAIN CHART VIEW (overlay): CALL / PUT arrows on the ENTRY candle.
--  Enter at the open of the arrow candle, 1-minute expiry. The arrow is
--  decided from closed candles only and never changes during the candle.
--  Setup marker on the confirmation candle: PB pullback, TR trend
--  continuation, BO breakout, RG range rejection. The score is NOT a
--  win probability.
-- =====================================================================
input_group {
    "Display",
    v2_show_setup = input { default = true, type = input.plot_visibility },
    v2_call_color = input { default = "#00E676", type = input.color },
    v2_put_color  = input { default = "#FF1744", type = input.color }
}
local cc, pc, BB, AB = v2_call_color, v2_put_color, shape_location.belowbar, shape_location.abovebar
plot_shape (SIG_DIR == 1, "CALL", shape_style.arrowup, shape_size.large, cc, BB, 0, "CALL", cc)
plot_shape (SIG_DIR == -1, "PUT", shape_style.arrowdown, shape_size.large, pc, AB, 0, "PUT", pc)
if v2_show_setup then
    local C, S, K = shape_style.circle, shape_size.tiny, SIG_KIND
    plot_shape (K == 1, "CALL PB", C, S, cc, BB, -1, "PB", cc)
    plot_shape (K == 2, "CALL TR", C, S, cc, BB, -1, "TR", cc)
